using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    async Task ApplyMigrationsAsync(AppDbContext db)
    {
        // EF Core 9 manages its own transactions during migration;
        // wrapping in a user transaction now throws.
        await db.Database.MigrateAsync();
    }
}

